const icon=(name,extra='')=>`<span class="icon"${extra?` ${extra}`:''}>${ICONS[name]||''}</span>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{const raw=String(v||'').trim();if(!/^https?:\/\//i.test(raw))return'';try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)?u.toString():''}catch{return''}};
const logoSrc=x=>x?.logoUrl&&x?.id?`/api/software/${Number(x.id)}/logo-file`:'';
const fmt=n=>Number(n||0).toLocaleString();
const count=n=>n==null?'Public total unavailable':Number(n).toLocaleString();
const bytes=n=>{n=Number(n||0);if(!n)return'N/A';const u=['B','KB','MB','GB'];const i=Math.min(3,Math.floor(Math.log(n)/Math.log(1024)));return`${(n/(1024**i)).toFixed(i?1:0)} ${u[i]}`};
const dateLabel=v=>{if(!v)return'N/A';const d=new Date(`${String(v).slice(0,10)}T00:00:00`);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})};
const dateTimeLabel=v=>{if(!v)return'No backup yet';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})};
const relativeTime=v=>{if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return'';const sec=Math.max(0,Math.floor((Date.now()-d.getTime())/1000));if(sec<45)return'Just now';if(sec<3600)return`${Math.floor(sec/60)} min ago`;if(sec<86400)return`${Math.floor(sec/3600)} hr ago`;if(sec<604800)return`${Math.floor(sec/86400)} day${Math.floor(sec/86400)===1?'':'s'} ago`;return d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:d.getFullYear()===new Date().getFullYear()?undefined:'numeric'})};
const languageLabel=()=> 'English';
const platformLabel=x=>{const raw=String(x?.platform||'').trim();if(!raw)return'Windows';const low=raw.toLowerCase();const hasWin=/windows/.test(low),hasMac=/macos|mac os|darwin/.test(low),hasLinux=/linux/.test(low);const names=[];if(hasWin)names.push('Windows');if(hasMac)names.push('macOS');if(hasLinux)names.push('Linux');return names.length?names.join(' / '):raw.replace(/\.Desktop|\.Universal/gi,'').trim()||raw};
const processorLabel=x=>{const raw=String(x?.processor||'').trim();const low=raw.toLowerCase();if(/\bdual[- ]?core\b|\b2[- ]?core\b/.test(low))return'2-core CPU';if(/\bquad[- ]?core\b|\b4[- ]?core\b/.test(low))return'4-core CPU';if(/\bhexa[- ]?core\b|\b6[- ]?core\b/.test(low))return'6-core CPU';if(/\bocta[- ]?core\b|\b8[- ]?core\b/.test(low))return'8-core CPU';if(raw&&!/(?:32|64)-bit\s+(?:x86|arm)|^(?:x86|x64|arm|arm64)\b|architecture-neutral|compatible processor|\((?:x86|x64|arm|arm64)\).*processor/i.test(raw)&&!/\b(intel|amd|ryzen|core\s+i[3579]|apple\s+m\d|snapdragon|xeon|athlon|celeron|pentium)\b/i.test(raw))return raw;return x?.requirementEstimates?.processor?(String(x?.ramRequirement||'').match(/(?:16|32)\s*GB/i)?'4-core CPU':'2-core CPU'):'4-core CPU'};
const storageLabel=v=>{const raw=String(v||'').trim();if(!raw)return'Automatic';const m=raw.match(/([\d.]+)\s*(TB|GB|MB|KB)/i);return m?`${m[1]} ${m[2].toUpperCase()}`:raw.replace(/\b(available|free|required|storage|disk space|space)\b/gi,'').replace(/\s{2,}/g,' ').trim()||'Automatic'};
const enrichedRevision=x=>Number(x?.metadataRevision||0)>=2;
const requirementValue=(x,v)=>v||'Automatic';
const graphicsLabel=v=>{const raw=String(v||'').trim();if(!raw)return'Automatic';const low=raw.toLowerCase();if(/^(no|not)\b/.test(low)&&/(gpu|graphic)/.test(low)||/(no dedicated gpu|required.*no gpu|gpu not required|graphics not required|no graphics required)/.test(low))return'Not required';return raw};
