async function loadLogoCandidates(x,{force=false}={}){
  const wrap=$('#logoCandidateGrid');if(!wrap||!x?.id)return;
  wrap.innerHTML='<div class="logo-candidate-loading">Finding six verified icon options…</div>';
  try{
    const data=await API(`/api/software/${x.id}/logo-candidates${force?'?refresh=1':''}`);
    const slots=[
      {key:'logo-dev-webp',label:'Logo.dev Verified Product',downloadFormat:'webp'},
      {key:'logos-apps-svg',label:'Logos-Apps SVG',downloadFormat:'svg'},
      {key:'official-site-logo',label:'Official Website Logo',downloadFormat:'png'},
      {key:'winget-manifest-logo',label:'WinGet Manifest Logo',downloadFormat:'png'},
      {key:'dashboard-icons-svg',label:'Dashboard Icons SVG',downloadFormat:'svg'},
      {key:'selfhst-svg',label:'selfh.st Icons SVG',downloadFormat:'svg'}
    ];
    const returned=new Map((data.candidates||[]).map(c=>[String(c.key||''),c]));
    const items=slots.map(slot=>{const hit=returned.get(slot.key)||{};return {...slot,...hit,key:slot.key,label:hit.label||slot.label,downloadFormat:hit.downloadFormat||slot.downloadFormat,available:Boolean(hit.available&&hit.previewUrl),previewUrl:hit.previewUrl||null}});
    wrap.innerHTML=items.map((c,i)=>{const size=c.width&&c.height?`${Math.round(c.width)}×${Math.round(c.height)}`:(String(c.format||'').toLowerCase()==='svg'?'Vector':'Verified source');const detail=c.matchedDomain?`${size} · ${c.matchedDomain}`:size;const unavailableReason=c.reason||'Refresh sources or use another verified option.';return `<article class="logo-candidate-card ${c.available?'':'unavailable'}"><div class="logo-candidate-top"><span class="logo-candidate-index">${i+1}</span><span class="logo-candidate-format">${esc(String(c.downloadFormat||'png').toUpperCase())}</span></div><div class="logo-candidate-preview">${c.available?`<img src="${esc(c.previewUrl)}" alt="${esc(x.name)} icon option ${i+1}" loading="eager">`:`<div class="logo-empty"><b>No exact icon</b><span>${esc(unavailableReason)}</span></div>`}</div><div class="logo-candidate-copy"><div class="logo-candidate-source" title="${esc(c.label||'Icon source')}">${esc(c.label||'Icon source')}</div><div class="logo-candidate-size">${c.available?esc(detail):'Unavailable'}</div></div>${c.available?`<button class="btn small primary logo-candidate-download" data-logo-source="${esc(c.key)}" data-logo-format="${esc(c.downloadFormat||'png')}">Download full-size ${esc(String(c.downloadFormat||'png').toUpperCase())}</button>`:`<button class="btn small" disabled>Unavailable</button>`}</article>`}).join('');
    wrap.querySelectorAll('[data-logo-source]').forEach(btn=>{btn.onclick=()=>{const c=items.find(v=>v.key===btn.dataset.logoSource);if(btn.dataset.logoFormat==='svg')downloadLogoCandidateSvg(x,c,btn);else if(btn.dataset.logoFormat==='webp')downloadLogoCandidateWebp(x,c,btn);else downloadLogoCandidatePNG(x,c,btn)}});
  }catch(e){wrap.innerHTML=`<div class="notice error">${esc(e.message||'Icon options could not be loaded.')}</div>`}
}



async function API(url,opt={}){const headers=new Headers(opt.headers||{});if(opt.body&&!headers.has('content-type')&&typeof opt.body==='string')headers.set('content-type','application/json');if(S.csrf&&opt.method&&opt.method!=='GET')headers.set('x-csrf-token',S.csrf);const r=await fetch(url,{credentials:'same-origin',...opt,headers});const ct=r.headers.get('content-type')||'';const d=ct.includes('json')?await r.json():{error:await r.text()};if(!r.ok||d.ok===false){const err=new Error(d.error||`Request failed (${r.status})`);err.status=r.status;err.data=d;throw err}return d}
async function bootstrap(){const d=await API('/api/bootstrap');S.csrf=d.csrfToken;S.data=d;return d}
const isAdmin=()=>S.data?.user?.role==='admin';
const initials=name=>String(name||'User').trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')||'U';
function avatarHtml(u,cls='profile-avatar'){return u?.hasAvatar&&u?.avatarUrl?`<img class="${cls}" src="${esc(u.avatarUrl)}" alt="${esc(u.name||'User')}">`:`<div class="${cls} avatar-fallback">${esc(initials(u?.name))}</div>`}
function normalizeRole(role){return String(role||'partner').toLowerCase()==='admin'?'admin':'partner'}
function profileRoleMarkup(u){const active=normalizeRole(u?.role||u?.roleLabel);const label=active==='admin'?'Admin':'Partner';return`<div class="profile-role-row"><span class="profile-role-pill ${active}"><span class="profile-role-icon">${icon('shield')}</span><span class="profile-role-current">${label}</span></span></div>`}
function profileCardInner(u){const name=u?.name||'HSWare User';const email=u?.email||'Signed in';return`<div class="profile-top"><div class="profile-media">${avatarHtml(u)}</div><div class="profile-main"><div class="profile-name" title="${esc(name)}">${esc(name)}</div><div class="profile-email" title="${esc(u?.email||'')}">${esc(email)}</div>${profileRoleMarkup(u)}</div></div><div class="profile-divider"></div><button class="profile-signout" id="logout" title="Sign out" aria-label="Sign out">${icon('logout')}<span>Logout</span></button>`}
const titles={dashboard:['Dashboard','Software ingest, verification and update management.'],catalog:['Software Catalog','Browse the complete verified WinGet catalog across 200 categories.'],detail:['Software Details','Review software metadata, package integrity, requirements and publishing state.'],new_software:['New Software','Import the next unseen verified WinGet software into your working queue.'],published:['Published Software','Your permanent software library after website publishing.'],updates:['Update Center','Review new upstream releases for your published software.'],settings:['Settings','Team access, backup and deployment controls.']};
function navItem(tab,label,iconName,badge=''){return`<button class="nav-btn ${S.tab===tab?'active':''}" data-nav="${tab}"><span><span class="nav-icon">${icon(iconName)}</span>${esc(label)}</span>${badge!==''?`<span class="badge">${fmt(badge)}</span>`:''}</button>`}
